WORD_PATH = "M128.2 24.768H134.086L150.55599999999998 63.0H142.78L139.216 54.252H122.638L119.182 63.0H111.568ZM136.84 48.42 130.954 32.868 124.96 48.42Z M152.71200000000002 37.08H158.86800000000002V41.238H158.976Q159.84 39.294 161.973 37.809Q164.10600000000002 36.324 167.02200000000002 36.324Q169.56 36.324 171.369 37.215Q173.178 38.106 174.339 39.56400000000001Q175.5 41.022000000000006 176.04000000000002 42.912000000000006Q176.58 44.802 176.58 46.8V63.0H170.10000000000002V48.636Q170.10000000000002 47.502 169.93800000000002 46.260000000000005Q169.776 45.018 169.23600000000002 44.019Q168.69600000000003 43.019999999999996 167.75100000000003 42.372Q166.806 41.724000000000004 165.24 41.724000000000004Q163.674 41.724000000000004 162.54000000000002 42.345Q161.406 42.966 160.67700000000002 43.938Q159.948 44.91 159.57 46.179Q159.192 47.448 159.192 48.744V63.0H152.71200000000002Z M178.952 37.08H186.134L193.37 55.926H193.478L199.904 37.08H206.654L194.396 68.562Q193.694 70.344 192.88400000000001 71.721Q192.074 73.098 190.94 74.043Q189.80599999999998 74.988 188.267 75.47399999999999Q186.728 75.96 184.56799999999998 75.96Q183.758 75.96 182.921 75.87899999999999Q182.084 75.798 181.22 75.582L181.76 69.966Q182.408 70.182 183.029 70.263Q183.65 70.344 184.19 70.344Q185.216 70.344 185.918 70.101Q186.62 69.858 187.106 69.345Q187.59199999999998 68.832 187.96999999999997 68.076Q188.34799999999998 67.32 188.78 66.294L190.076 63.0Z M204.814 24.768H212.428L222.95799999999997 54.198H223.17399999999998L233.81199999999998 24.768H241.15599999999998L225.82 63.0H219.934Z M243.31199999999998 37.08H249.79199999999997V63.0H243.31199999999998ZM242.39399999999998 28.278Q242.39399999999998 26.712000000000003 243.55499999999998 25.551000000000002Q244.71599999999998 24.39 246.49799999999996 24.39Q248.27999999999997 24.39 249.49499999999998 25.497Q250.70999999999998 26.604 250.70999999999998 28.278Q250.70999999999998 29.951999999999998 249.49499999999998 31.058999999999997Q248.27999999999997 32.166 246.49799999999996 32.166Q244.71599999999998 32.166 243.55499999999998 31.005Q242.39399999999998 29.844 242.39399999999998 28.278Z M254.32399999999998 57.275999999999996 268.30999999999995 42.263999999999996H254.97199999999998V37.08H276.032V42.804L261.99199999999996 57.708H276.67999999999995V63.0H254.32399999999998Z"
MARK = '''<g mask="url(#node-space)" fill="none" stroke-width="8" stroke-linejoin="round">
<path d="M25 48H53" class="teal"/>
<path d="M10 68L37 18L67 68" class="blue"/>
<path d="M67 68L94 18" class="teal"/>
</g>
<g class="blue-fill"><circle cx="10" cy="68" r="5"/><circle cx="37" cy="18" r="5"/></g>
<circle class="teal-fill" cx="67" cy="68" r="5"/>'''

def svg(mode='auto', icon=False):
    light = '.ink{fill:#182235}.blue{stroke:#365FD1}.teal{stroke:#19897E}.blue-fill{fill:#365FD1}.teal-fill{fill:#19897E}'
    dark = '.ink{fill:#F0F4FC}.blue{stroke:#88A5FF}.teal{stroke:#64D6C4}.blue-fill{fill:#88A5FF}.teal-fill{fill:#64D6C4}'
    style = dark if mode == 'dark' else light
    if mode == 'auto':
        style += '@media(prefers-color-scheme:dark){' + dark + '}'
    width = 104 if icon else 296
    body = MARK if icon else MARK + f'<path class="ink" d="{WORD_PATH}"/>'
    return f'''<svg xmlns="http://www.w3.org/2000/svg" width="{width}" height="88" viewBox="0 0 {width} 88" role="img" aria-labelledby="brand-title brand-desc">
<title id="brand-title">AnyViz</title>
<desc id="brand-desc">An A/V monogram drawn as connected data points, paired with the AnyViz wordmark.</desc>
<style>{style}</style>
<defs><mask id="node-space"><rect width="104" height="88" fill="white"/><g fill="black"><circle cx="10" cy="68" r="8"/><circle cx="37" cy="18" r="8"/><circle cx="67" cy="68" r="8"/></g></mask></defs>
{body}
</svg>
'''

def write_assets():
    for mode, suffix in [('auto',''),('light','-light'),('dark','-dark')]:
        for name, icon in [('wordmark',False),('icon',True)]:
            (ROOT/'assets'/f'{name}{suffix}.svg').write_text(svg(mode,icon))
    print('Built six theme-aware AnyViz SVG assets.')

if __name__ == '__main__':
    write_assets()
